import { StaticProxiesService } from "./staticProxiesService.ts";
import { AccountService } from "./accountService.ts";
import { SecurityService } from "./securityService.ts";
import { assertEquals, assertGreaterOrEqual } from "jsr:@std/assert@1";

Deno.test("StaticProxiesService.getCountries", async t => {
	let securityToken: string | undefined;
	await t.step({
		name: "prerequisite: authorization / authentication",
		fn: async t => {
			let token: string | undefined;
			await t.step({
				name: "Register anonymous account & get token",
				fn: async () => {
					const accountService = new AccountService();
					const account = await accountService.registerAnonymous();
					token = account.value;
				}
			});
			await t.step({
				name: "Get security token",
				fn: async () => {
					if (!token) throw new Error("Account token is undefined");
					const securityService = new SecurityService();
					const securityTokenWrap = await securityService.getSecurityToken(token);
					securityToken = securityTokenWrap.value;
				}
			});
		}
	})
	if (!securityToken) throw new Error("Security token is undefined");
	const staticProxiesService = new StaticProxiesService(securityToken);
	const countries = await staticProxiesService.getCountries();
	assertGreaterOrEqual(countries.elements.length, 3, "Countries list is too small");
});